begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('14100000-0000-0000-0000-000000000001','create-sales@test.invalid','{}'),('14100000-0000-0000-0000-000000000002','create-manager@test.invalid','{}');
insert into public.profile_roles(profile_id,role_id) values('14100000-0000-0000-0000-000000000001','sales'),('14100000-0000-0000-0000-000000000002','sales_manager');
create temp table create_inputs as select jsonb_build_object('customer_name','Consultant created','contact_number','123','query_information','New enquiry','media_platform_id',(select id from public.sales_desk_media_platforms where is_active limit 1)) payload;
grant select on create_inputs to authenticated;
set local role authenticated;
set local request.jwt.claims='{"sub":"14100000-0000-0000-0000-000000000001","role":"authenticated"}';
select is((public.sales_desk_configuration()->>'can_create')::boolean,true,'consultant role Create default is exposed to the UI');
select lives_ok($$select public.create_sales_desk_rfq((select payload from create_inputs))$$,'consultant with Create can create an RFQ');
reset role;
select is((select count(*) from public.sales_desk_rfqs where created_by='14100000-0000-0000-0000-000000000001'),1::bigint,'consultant creation persists');
select is((select count(*) from public.sales_desk_rfq_audit where actor_user_id='14100000-0000-0000-0000-000000000001' and action='created'),1::bigint,'consultant creation is attributed and audited');
insert into public.application_user_permission_overrides(profile_id,app_id,permission_key,enabled) values('14100000-0000-0000-0000-000000000001','sales_desk','sales_desk.create',false),('14100000-0000-0000-0000-000000000002','sales_desk','sales_desk.create',false);
set local role authenticated;
select is((public.sales_desk_configuration()->>'can_create')::boolean,false,'revoking Create updates capability without changing the session role');
select throws_ok($$select public.create_sales_desk_rfq((select payload from create_inputs))$$,'42501',null,'consultant Create deny is enforced by database');
set local request.jwt.claims='{"sub":"14100000-0000-0000-0000-000000000002","role":"authenticated"}';
select is((public.sales_desk_configuration()->>'can_create')::boolean,false,'manager role does not override Create deny');
select throws_ok($$select public.create_sales_desk_rfq((select payload from create_inputs))$$,'42501',null,'denied manager cannot create');
reset role;
-- Editable role defaults and per-user grants use the same effective permission.
delete from public.application_role_permissions where role_id='sales' and permission_key='sales_desk.create';
update public.application_user_permission_overrides set enabled=true where profile_id='14100000-0000-0000-0000-000000000001' and permission_key='sales_desk.create';
set local role authenticated;
set local request.jwt.claims='{"sub":"14100000-0000-0000-0000-000000000001","role":"authenticated"}';
select is((public.sales_desk_configuration()->>'can_create')::boolean,true,'user allow overrides role default deny');
select lives_ok($$select public.create_sales_desk_rfq((select payload from create_inputs))$$,'explicit consultant grant permits creation');
reset role;
insert into public.application_user_permission_overrides(profile_id,app_id,permission_key,enabled) values('14100000-0000-0000-0000-000000000001','sales_desk','sales_desk.assign',false);
insert into public.sales_desk_sales_codes(id,code) values('14100000-0000-0000-0001-000000000001','CREATE-ASSIGN');
set local role authenticated;
select is((public.sales_desk_configuration()->>'can_assign')::boolean,false,'separate assignment permission is exposed to creation form');
select throws_ok($$select public.create_sales_desk_rfq((select payload from create_inputs)||'{"sales_code_id":"14100000-0000-0000-0001-000000000001"}')$$,'42501',null,'Create does not imply assignment authority');
reset role;
insert into public.application_user_permission_overrides(profile_id,app_id,permission_key,enabled) values('14100000-0000-0000-0000-000000000001','sales_desk','sales_desk.view',false);
set local role authenticated;
select throws_ok($$select public.create_sales_desk_rfq((select payload from create_inputs))$$,'42501',null,'Create cannot bypass denied View access');
reset role;
select ok(not has_function_privilege('anon','public.create_sales_desk_rfq(jsonb)','execute'),'anonymous creation remains blocked');
select ok(not has_table_privilege('authenticated','public.sales_desk_rfqs','insert'),'browser cannot bypass transactional creation');
select * from finish();
rollback;
